// Microbes in Human Welfare - Question Bank
// Format follows the same schema used across the practice app:
// { id, type, question, options, correctIndex, explanation, difficulty }
// type: 'mcq' | 'assertion' | 'matching' | 'statement' | 'count'

export const MICROBES_HUMAN_WELFARE = [

  // ============ MICROBES IN HOUSEHOLD PRODUCTS ============
  { id: 'mhw-1', type: 'mcq', question: 'Curd is formed from milk due to the activity of which group of microbes?', options: ['Lactic acid bacteria (LAB) such as Lactobacillus', 'Saccharomyces cerevisiae', 'Aspergillus niger', 'Penicillium notatum'], correctIndex: 0, explanation: 'Lactic acid bacteria (LAB), such as Lactobacillus, grow in milk and convert it to curd, also producing vitamin B12.', difficulty: 'easy' },
  { id: 'mhw-2', type: 'mcq', question: 'The small amount of curd added to fresh milk to set it as curd, containing millions of LAB, is known as the:', options: ['Starter culture (inoculum)', 'Culture medium', 'Fermenter', 'Wort'], correctIndex: 0, explanation: 'A small quantity of curd added to fresh milk as inoculum, which multiplies and converts milk into curd, is called the starter culture.', difficulty: 'easy' },
  { id: 'mhw-3', type: 'mcq', question: 'Apart from converting milk to curd, lactic acid bacteria also improve nutritional quality by producing:', options: ['Vitamin C', 'Vitamin B12', 'Vitamin A', 'Vitamin D'], correctIndex: 1, explanation: 'Lactic acid bacteria multiplying in milk during curd formation also produce significant quantities of vitamin B12.', difficulty: 'medium' },
  { id: 'mhw-4', type: 'mcq', question: 'The numerous small holes or "eyes" seen in Swiss cheese are produced due to the release of large amounts of ______ by a specific bacterium.', options: ['Carbon dioxide gas', 'Alcohol', 'Lactic acid', 'Citric acid'], correctIndex: 0, explanation: 'The bacterium Propionibacterium sharmanii produces large amounts of CO2 during fermentation of Swiss cheese, creating its characteristic large holes.', difficulty: 'medium' },
  { id: 'mhw-5', type: 'mcq', question: 'The dough used for making foods such as idli and dosa rises due to fermentation carried out by:', options: ['Bacteria', 'Yeast', 'Fungi other than yeast', 'Algae'], correctIndex: 1, explanation: 'Bacteria (and in some contexts yeast) ferment the dough used for making foods like idli and dosa; the dough rises due to the production of gases like CO2 during fermentation.', difficulty: 'medium' },
  { id: 'mhw-6', type: 'mcq', question: 'Toddy, a traditional fermented beverage, is prepared using the fermenting action of which type of microbe?', options: ['Bacteria', 'Yeast', 'Protozoa', 'Virus'], correctIndex: 1, explanation: 'Toddy is a common name for a traditional fermented beverage made by the fermenting action of yeasts.', difficulty: 'medium' },
  { id: 'mhw-7', type: 'assertion', question: 'Assertion (A): Curd generally has better nutritional quality than the milk from which it is made.\nReason (R): The lactic acid bacteria involved in curd formation multiply in milk and produce additional vitamin B12, apart from converting lactose to lactic acid.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The additional production of vitamin B12 by LAB, alongside the fermentation itself, correctly explains why curd has improved nutritional quality compared to milk.', difficulty: 'medium' },
  { id: 'mhw-8', type: 'count', question: 'Consider the following statements about household applications of microbes:\n1. Lactobacillus is used to prepare curd from milk.\n2. Propionibacterium sharmanii is responsible for the large holes in Swiss cheese.\n3. Toddy is prepared using the fermenting action of bacteria, not yeast.\n4. A starter culture contains millions of lactic acid bacteria.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — toddy is prepared using yeast, not bacteria.', difficulty: 'medium' },

  // ============ MICROBES IN INDUSTRIAL PRODUCTS: FERMENTED BEVERAGES ============
  { id: 'mhw-9', type: 'mcq', question: 'The yeast most commonly used for the commercial production of ethanol and fermented (alcoholic) beverages is:', options: ['Aspergillus niger', 'Saccharomyces cerevisiae', 'Penicillium notatum', 'Lactobacillus'], correctIndex: 1, explanation: 'Saccharomyces cerevisiae, commonly called brewer\'s yeast, is used commercially for the production of ethanol/alcoholic beverages by fermenting sugars.', difficulty: 'easy' },
  { id: 'mhw-10', type: 'mcq', question: 'For commercial production of alcoholic drinks, the fermentation is carried out without ______, as this favours the metabolic pathway producing ethanol.', options: ['Sugar', 'Light', 'Oxygen (i.e., anaerobic conditions are used)', 'Water'], correctIndex: 2, explanation: 'Alcoholic fermentation by yeast occurs anaerobically (without oxygen), converting sugars to ethanol and carbon dioxide.', difficulty: 'medium' },
  { id: 'mhw-11', type: 'mcq', question: 'Different types of fermented beverages are produced depending on the type of raw material used for fermentation and the type of processing done. Wine and beer are prepared without:', options: ['Sugar', 'Yeast', 'Distillation', 'Water'], correctIndex: 2, explanation: 'Wine and beer are produced without distillation, whereas whisky, brandy and rum are produced by distillation of the fermented broth.', difficulty: 'medium' },
  { id: 'mhw-12', type: 'assertion', question: 'Assertion (A): Wine and beer are prepared by fermenting fruit juices or grains but do not require distillation.\nReason (R): Distillation is a step required only when higher alcohol content beverages such as whisky and brandy are to be prepared from the fermented broth.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Since distillation increases alcohol concentration and is used to prepare stronger beverages, its absence in wine/beer preparation is correctly explained by R.', difficulty: 'medium' },

  // ============ ANTIBIOTICS ============
  { id: 'mhw-13', type: 'mcq', question: 'The first antibiotic to be discovered, penicillin, was accidentally discovered by:', options: ['Louis Pasteur', 'Alexander Fleming', 'Robert Koch', 'Edward Jenner'], correctIndex: 1, explanation: 'Alexander Fleming, while working on Staphylococcus bacteria, accidentally discovered penicillin in 1928 from the mould Penicillium notatum.', difficulty: 'easy' },
  { id: 'mhw-14', type: 'mcq', question: 'Fleming observed that a mould contaminating his bacterial culture plate inhibited bacterial growth around it; this mould was later identified as:', options: ['Aspergillus niger', 'Penicillium notatum', 'Saccharomyces cerevisiae', 'Trichoderma polysporum'], correctIndex: 1, explanation: 'The mould was identified as Penicillium notatum, and the antibacterial substance it produced was called penicillin.', difficulty: 'easy' },
  { id: 'mhw-15', type: 'mcq', question: 'Which scientists are credited with establishing the commercial potential of penicillin as an effective antibiotic, following Fleming\'s discovery?', options: ['Ernst Chain and Howard Florey', 'Robert Koch and Louis Pasteur', 'Edward Jenner and Alexander Fleming', 'Waksman and Woodruff'], correctIndex: 0, explanation: 'Ernst Chain and Howard Florey established the commercial and clinical importance of penicillin, especially during World War II.', difficulty: 'medium' },
  { id: 'mhw-16', type: 'mcq', question: 'Antibiotics are chemical substances produced by certain microbes that can:', options: ['Kill or retard the growth of other (disease-causing) microbes', 'Only kill viruses', 'Only be used in agriculture', 'Only stimulate the immune system'], correctIndex: 0, explanation: 'Antibiotics are chemical substances, produced by some microbes, that can kill or inhibit the growth of other disease-causing microbes.', difficulty: 'easy' },
  { id: 'mhw-17', type: 'mcq', question: 'Which of the following is a soil actinomycete used for the production of the antibiotic streptomycin?', options: ['Streptococcus lactis', 'Streptomyces griseus', 'Penicillium notatum', 'Bacillus subtilis'], correctIndex: 1, explanation: 'Streptomycin is produced by the soil actinomycete Streptomyces griseus.', difficulty: 'medium' },
  { id: 'mhw-18', type: 'assertion', question: 'Assertion (A): Antibiotics have revolutionised the treatment of many infectious diseases.\nReason (R): Antibiotics selectively kill or inhibit disease-causing microbes without harming the host in the doses typically used, making them effective and relatively safe therapeutic agents.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The selective action of antibiotics against microbes while sparing the host correctly explains their revolutionary impact on treating infectious diseases.', difficulty: 'medium' },
  { id: 'mhw-19', type: 'count', question: 'Consider the following statements about antibiotics and their discovery:\n1. Penicillin was accidentally discovered by Alexander Fleming.\n2. The mould responsible for producing penicillin is Penicillium notatum.\n3. Ernst Chain and Howard Florey established the clinical importance of penicillin.\n4. Streptomycin is produced by a species of Penicillium.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 3 are correct. Statement 4 is wrong — streptomycin is produced by Streptomyces griseus (an actinomycete), not Penicillium.', difficulty: 'medium' },

  // ============ CHEMICALS, ENZYMES, OTHER BIOACTIVE MOLECULES ============
  { id: 'mhw-20', type: 'mcq', question: 'Citric acid, used commercially in the food and beverage industry, is commercially produced using which fungus?', options: ['Aspergillus niger', 'Saccharomyces cerevisiae', 'Penicillium notatum', 'Trichoderma harzianum'], correctIndex: 0, explanation: 'Citric acid is produced commercially by fermentation using the fungus Aspergillus niger.', difficulty: 'medium' },
  { id: 'mhw-21', type: 'mcq', question: 'Lactic acid, used in various food and pharmaceutical applications, is commercially produced with the help of the bacterium:', options: ['Lactobacillus', 'Acetobacter aceti', 'Clostridium butylicum', 'Streptococcus'], correctIndex: 0, explanation: 'Lactic acid is produced commercially using Lactobacillus species.', difficulty: 'medium' },
  { id: 'mhw-22', type: 'mcq', question: 'Acetic acid (vinegar), widely used as a preservative and flavouring agent, is commercially produced using the bacterium:', options: ['Acetobacter aceti', 'Lactobacillus', 'Clostridium butylicum', 'Aspergillus niger'], correctIndex: 0, explanation: 'Acetic acid (vinegar) is commercially produced using Acetobacter aceti.', difficulty: 'medium' },
  { id: 'mhw-23', type: 'mcq', question: 'Butyric acid, an organic acid used in industrial applications, is produced with the help of:', options: ['Clostridium butylicum', 'Aspergillus niger', 'Saccharomyces cerevisiae', 'Streptomyces griseus'], correctIndex: 0, explanation: 'Butyric acid is commercially produced using Clostridium butylicum.', difficulty: 'medium' },
  { id: 'mhw-24', type: 'mcq', question: 'The digestive enzyme lipase, used to remove oily stains from clothes and included in detergent formulations, is obtained from which fungus?', options: ['Aspergillus niger', 'Penicillium notatum', 'Trichoderma polysporum', 'Streptomyces griseus'], correctIndex: 0, explanation: 'Lipases, used in detergent formulations to remove oily stains, are produced commercially using the fungus Aspergillus niger.', difficulty: 'medium' },
  { id: 'mhw-25', type: 'mcq', question: 'The enzyme streptokinase, produced by the bacterium Streptococcus, is used clinically as a:', options: ['Blood clot dissolving (clot buster) agent for patients recovering from myocardial infarction', 'Sedative', 'Antibiotic against bacterial infection', 'Digestive enzyme'], correctIndex: 0, explanation: 'Streptokinase, produced by Streptococcus and modified by genetic engineering, is used as a clot-buster in patients who have suffered a heart attack (myocardial infarction).', difficulty: 'medium' },
  { id: 'mhw-26', type: 'mcq', question: 'Cyclosporin A, a widely used immunosuppressive agent given to organ-transplant patients, is produced by the fungus:', options: ['Trichoderma polysporum', 'Monascus purpureus', 'Aspergillus niger', 'Penicillium notatum'], correctIndex: 0, explanation: 'Cyclosporin A, used to suppress the immune system in organ-transplant recipients, is produced by the fungus Trichoderma polysporum.', difficulty: 'medium' },
  { id: 'mhw-27', type: 'mcq', question: 'Statins, used as blood-cholesterol lowering agents, are produced commercially using the yeast:', options: ['Monascus purpureus', 'Saccharomyces cerevisiae', 'Streptomyces griseus', 'Aspergillus niger'], correctIndex: 0, explanation: 'Statins, which competitively inhibit the enzyme responsible for cholesterol synthesis, are produced by the yeast Monascus purpureus.', difficulty: 'medium' },
  { id: 'mhw-28', type: 'mcq', question: 'Statins act by competitively inhibiting an enzyme responsible for the synthesis of:', options: ['Cholesterol', 'Ethanol', 'Vitamin B12', 'Insulin'], correctIndex: 0, explanation: 'Statins lower blood cholesterol levels by competitively inhibiting the enzyme responsible for cholesterol synthesis in the body.', difficulty: 'medium' },
  { id: 'mhw-29', type: 'matching', question: 'Match Column I (microbe) with Column II (product):\nColumn I: A. Aspergillus niger  B. Streptococcus  C. Trichoderma polysporum  D. Monascus purpureus\nColumn II: i. Statins  ii. Streptokinase  iii. Citric acid  iv. Cyclosporin A', options: ['A-iii, B-ii, C-iv, D-i', 'A-i, B-ii, C-iii, D-iv', 'A-iii, B-iv, C-ii, D-i', 'A-ii, B-iii, C-i, D-iv'], correctIndex: 0, explanation: 'Aspergillus niger — citric acid; Streptococcus — streptokinase; Trichoderma polysporum — cyclosporin A; Monascus purpureus — statins.', difficulty: 'hard' },
  { id: 'mhw-30', type: 'matching', question: 'Match Column I (organic acid/product) with Column II (producing microbe):\nColumn I: A. Lactic acid  B. Acetic acid  C. Butyric acid  D. Lipase\nColumn II: i. Clostridium butylicum  ii. Aspergillus niger  iii. Lactobacillus  iv. Acetobacter aceti', options: ['A-iii, B-iv, C-i, D-ii', 'A-iv, B-iii, C-ii, D-i', 'A-iii, B-i, C-iv, D-ii', 'A-ii, B-iii, C-iv, D-i'], correctIndex: 0, explanation: 'Lactic acid — Lactobacillus; Acetic acid — Acetobacter aceti; Butyric acid — Clostridium butylicum; Lipase — Aspergillus niger.', difficulty: 'hard' },
  { id: 'mhw-31', type: 'assertion', question: 'Assertion (A): Streptokinase produced naturally by Streptococcus is modified using genetic engineering before being used clinically.\nReason (R): Genetic modification of streptokinase makes it more effective and reduces the immune response it may otherwise trigger when introduced into the human body.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Genetic modification of streptokinase improves its clinical usability, correctly explaining why the naturally produced enzyme is modified before use.', difficulty: 'hard' },
  { id: 'mhw-32', type: 'count', question: 'Consider the following statements about industrial products of microbes:\n1. Citric acid is produced using Aspergillus niger.\n2. Lipases used in detergents are obtained from Aspergillus niger.\n3. Cyclosporin A is produced using Streptococcus.\n4. Statins are produced using Monascus purpureus.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — cyclosporin A is produced by Trichoderma polysporum, not Streptococcus.', difficulty: 'medium' },
  { id: 'mhw-33', type: 'statement', question: 'Statement I: Statins help lower blood cholesterol by inhibiting an enzyme involved in cholesterol biosynthesis.\nStatement II: Statins are produced commercially using genetically modified strains of Aspergillus niger.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 2, explanation: 'Statement I is correct. Statement II is incorrect — statins are produced using the yeast Monascus purpureus, not Aspergillus niger.', difficulty: 'medium' },

  // ============ MICROBES IN SEWAGE TREATMENT ============
  { id: 'mhw-34', type: 'mcq', question: 'The large-scale treatment of domestic wastewater (sewage) before its release into natural water bodies is primarily carried out with the help of:', options: ['Chemical treatment only', 'Heterotrophic microbes naturally present in sewage', 'Physical filtration only, without microbes', 'Genetically modified viruses'], correctIndex: 1, explanation: 'Sewage treatment relies mainly on the activity of heterotrophic microbes naturally present in the sewage to break down organic matter.', difficulty: 'easy' },
  { id: 'mhw-35', type: 'mcq', question: 'The first stage of sewage treatment, involving physical removal of large and small particles through filtration and sedimentation, is called:', options: ['Primary treatment', 'Secondary treatment', 'Tertiary treatment', 'Anaerobic digestion'], correctIndex: 0, explanation: 'Primary treatment involves physical removal of solids (floating debris, grit, and other particulate matter) through sequential filtration and sedimentation.', difficulty: 'medium' },
  { id: 'mhw-36', type: 'mcq', question: 'The stage of sewage treatment that primarily involves biological processes, using microbes to break down organic matter, is called:', options: ['Primary treatment', 'Secondary treatment (biological treatment)', 'Screening', 'Grit removal'], correctIndex: 1, explanation: 'Secondary (or biological) treatment involves the use of microbes to further break down and reduce the organic content of the effluent from primary treatment.', difficulty: 'medium' },
  { id: 'mhw-37', type: 'mcq', question: 'During secondary sewage treatment, the primary effluent is passed into large aeration tanks where it is:', options: ['Continuously agitated and air is pumped into it, allowing aerobic microbes to grow and consume organic matter', 'Frozen to preserve microbial activity', 'Treated with strong acids', 'Left completely undisturbed'], correctIndex: 0, explanation: 'In the aeration tank of secondary treatment, the effluent is agitated mechanically and air is pumped in, promoting vigorous growth of aerobic microbes that consume the bulk of the organic matter.', difficulty: 'medium' },
  { id: 'mhw-38', type: 'mcq', question: 'The parameter used to measure the amount of organic matter present in polluted water, based on the oxygen consumed by microbes during its degradation, is called:', options: ['pH value', 'Biochemical Oxygen Demand (BOD)', 'Total dissolved solids', 'Turbidity index'], correctIndex: 1, explanation: 'BOD refers to the amount of oxygen consumed by microorganisms while decomposing organic matter present in a given volume of water sample; higher BOD indicates greater pollution load.', difficulty: 'medium' },
  { id: 'mhw-39', type: 'mcq', question: 'A high BOD (Biochemical Oxygen Demand) value in a water sample generally indicates:', options: ['Low pollution potential', 'High organic pollution load in the water', 'Absence of microbes in the water', 'High dissolved oxygen content'], correctIndex: 1, explanation: 'A higher BOD indicates more organic matter present, which will require more oxygen to be broken down by microbes, reflecting a higher pollution load.', difficulty: 'medium' },
  { id: 'mhw-40', type: 'mcq', question: 'The solid part that settles down during secondary sewage treatment, formed mainly of bacterial "flocs", is called:', options: ['Sludge', 'Effluent', 'Bar screen residue', 'Sediment sludge cake'], correctIndex: 0, explanation: 'The floc (masses of bacteria associated with fungal filaments) settles down in the settling tank, forming activated sludge.', difficulty: 'medium' },
  { id: 'mhw-41', type: 'mcq', question: 'Bacterial "flocs" that develop during secondary treatment are important because they:', options: ['Are toxic and must be discarded entirely', 'Significantly reduce the BOD of wastewater by facilitating microbial consumption of organic matter', 'Increase the BOD of wastewater', 'Have no role in sewage treatment'], correctIndex: 1, explanation: 'The bacterial flocs, comprising masses of bacteria associated with fungal filaments, help in significantly reducing the BOD of the wastewater.', difficulty: 'medium' },
  { id: 'mhw-42', type: 'mcq', question: 'A small part of the sludge, formed during secondary sewage treatment, is pumped back into the aeration tank as:', options: ['Activated sludge inoculum', 'Waste for disposal', 'A dye', 'Solid fuel'], correctIndex: 0, explanation: 'A part of the sludge is pumped back into the aeration tank as inoculum, and the remaining major part is transferred into anaerobic sludge digesters.', difficulty: 'medium' },
  { id: 'mhw-43', type: 'mcq', question: 'In an anaerobic sludge digester, the major bulk of sludge is pumped and acted upon by which type of microbes?', options: ['Aerobic bacteria producing oxygen', 'Anaerobic bacteria, including methanogens', 'Only fungi', 'Only algae'], correctIndex: 1, explanation: 'In anaerobic sludge digesters, anaerobic bacteria, including methanogens, digest the bacteria and fungi present in the sludge.', difficulty: 'medium' },
  { id: 'mhw-44', type: 'mcq', question: 'The mixture of gases (methane, hydrogen sulphide, carbon dioxide) produced during anaerobic digestion of sludge is used commercially as a source of:', options: ['Drinking water', 'Energy (biogas)', 'Fertiliser only, with no energy value', 'Antibiotics'], correctIndex: 1, explanation: 'Anaerobic digestion of sludge produces a mixture of gases like methane, hydrogen sulphide and CO2, collectively known as biogas, which can be used as a source of energy.', difficulty: 'medium' },
  { id: 'mhw-45', type: 'mcq', question: 'The clear, treated effluent obtained after secondary treatment, having greatly reduced BOD, is typically:', options: ['Discharged into natural water bodies like rivers and streams', 'Reused as drinking water directly without any further treatment', 'Stored indefinitely without release', 'Converted directly to biogas'], correctIndex: 0, explanation: 'The treated effluent, with significantly reduced BOD, can be safely discharged into natural water bodies.', difficulty: 'medium' },
  { id: 'mhw-46', type: 'assertion', question: 'Assertion (A): A high BOD value of a water sample indicates a high level of organic pollution.\nReason (R): Greater organic matter in the water requires more oxygen for its microbial degradation, so BOD serves as an indirect measure of the pollution load.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The direct relationship between organic matter content and oxygen demand for its degradation correctly explains why BOD reflects pollution levels.', difficulty: 'medium' },
  { id: 'mhw-47', type: 'assertion', question: 'Assertion (A): Sludge from the settling tank is not entirely discarded but partly reused within the sewage treatment plant.\nReason (R): A small part of the sludge, rich in useful microbes, is recycled back into the aeration tank to serve as inoculum for further treatment of incoming sewage.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Recycling part of the sludge as inoculum maintains an active microbial population for ongoing treatment, correctly explaining the reuse practice.', difficulty: 'medium' },
  { id: 'mhw-48', type: 'assertion', question: 'Assertion (A): Anaerobic digesters used in sewage treatment plants also help generate useful biogas.\nReason (R): The anaerobic bacteria (methanogens) acting on the sludge produce a mixture of gases, largely methane, which can be used as fuel.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The production of methane-rich biogas by methanogens during anaerobic digestion correctly explains why sludge digesters also serve as energy sources.', difficulty: 'medium' },
  { id: 'mhw-49', type: 'count', question: 'Consider the following statements about sewage treatment:\n1. Primary treatment mainly involves physical removal of solids by filtration and sedimentation.\n2. Secondary treatment relies primarily on chemical disinfectants, not microbes.\n3. BOD is a measure of the oxygen required by microbes to decompose organic matter in a water sample.\n4. Activated sludge refers to the settled solid part, mainly bacterial flocs, formed during secondary treatment.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is wrong — secondary treatment relies primarily on microbes, not chemical disinfectants.', difficulty: 'medium' },
  { id: 'mhw-50', type: 'count', question: 'Consider the following statements about the sewage treatment process, in order:\n1. Effluent from primary treatment is passed into an aeration tank.\n2. Aerobic microbes in the aeration tank consume a major part of the organic matter, reducing BOD.\n3. Bacterial flocs formed during aeration are removed and discarded completely.\n4. The clear supernatant, with reduced BOD, is released into natural water bodies.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — a part of the settled sludge (flocs) is recycled as inoculum, not entirely discarded.', difficulty: 'hard' },
  { id: 'mhw-51', type: 'statement', question: 'Statement I: Secondary (biological) treatment of sewage is aimed at reducing the BOD of the wastewater using microbial action.\nStatement II: The effluent released after secondary treatment has a BOD equal to or higher than that of raw, untreated sewage.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 2, explanation: 'Statement I is correct. Statement II is incorrect — the effluent released after secondary treatment has a significantly reduced BOD compared to raw sewage.', difficulty: 'medium' },
  { id: 'mhw-52', type: 'matching', question: 'Match Column I (sewage treatment stage/term) with Column II (description):\nColumn I: A. Primary treatment  B. Secondary treatment  C. BOD  D. Anaerobic sludge digester\nColumn II: i. Measure of oxygen needed to degrade organic matter  ii. Physical removal of solids  iii. Biological treatment using aerobic microbes  iv. Produces biogas from sludge', options: ['A-ii, B-iii, C-i, D-iv', 'A-i, B-ii, C-iii, D-iv', 'A-iii, B-ii, C-iv, D-i', 'A-ii, B-i, C-iv, D-iii'], correctIndex: 0, explanation: 'Primary treatment — physical removal; Secondary treatment — biological (aerobic microbes); BOD — measure of oxygen demand; Anaerobic sludge digester — biogas production.', difficulty: 'medium' },

  // ============ MICROBES IN PRODUCTION OF BIOGAS ============
  { id: 'mhw-53', type: 'mcq', question: 'Biogas, a mixture of gases produced by the microbial activity of certain bacteria, is composed mainly of:', options: ['Methane, carbon dioxide, hydrogen and hydrogen sulphide', 'Only oxygen and nitrogen', 'Only carbon monoxide', 'Only hydrogen'], correctIndex: 0, explanation: 'Biogas is a mixture of gases, mainly methane (50–70%), produced by the activity of methanogenic bacteria along with carbon dioxide, hydrogen and hydrogen sulphide.', difficulty: 'medium' },
  { id: 'mhw-54', type: 'mcq', question: 'The bacteria responsible for producing large amounts of methane, together with CO2 and H2, from cellulosic material, are collectively called:', options: ['Nitrifying bacteria', 'Methanogens (e.g., Methanobacterium)', 'Denitrifying bacteria', 'Lactic acid bacteria'], correctIndex: 1, explanation: 'Methanogens, such as Methanobacterium, grow anaerobically on cellulosic material and produce large amounts of methane along with CO2 and H2.', difficulty: 'medium' },
  { id: 'mhw-55', type: 'mcq', question: 'Methanogens found in the rumen (a part of the stomach) of ruminant animals such as cattle and buffalo help the animal to:', options: ['Digest cellulose and produce methane as a by-product', 'Digest fats only', 'Fight bacterial diseases', 'Synthesise vitamin B12 alone'], correctIndex: 0, explanation: 'The rumen of cattle contains a large population of methanogens that help in the digestion of cellulose, producing methane as a by-product, which contributes to livestock dung being rich in these bacteria.', difficulty: 'medium' },
  { id: 'mhw-56', type: 'mcq', question: 'The dung of ruminant animals, being rich in cellulolytic microbes including methanogenic bacteria, is commonly used to prepare:', options: ['Antibiotics', 'Gobar gas (biogas) using biogas plants', 'Fermented beverages', 'Statins'], correctIndex: 1, explanation: 'Cattle dung, rich in methanogens (from the rumen), is used to prepare gobar gas (biogas) in biogas plants, which is used as fuel for cooking and lighting.', difficulty: 'easy' },
  { id: 'mhw-57', type: 'mcq', question: 'A biogas plant essentially consists of a concrete tank where the bio-waste (e.g., cattle dung slurry) is fed and fermented anaerobically; the tank has a:', options: ['Floating cover that rises as gas is produced', 'Fixed glass roof', 'No cover of any kind', 'A cover permanently sealed shut'], correctIndex: 0, explanation: 'A biogas plant has a floating cover that moves up as biogas accumulates, and this gas is then drawn off through a pipe to be used as fuel.', difficulty: 'medium' },
  { id: 'mhw-58', type: 'mcq', question: 'Compared to ordinary firewood or cow dung cakes, biogas as a fuel is considered advantageous mainly because:', options: ['It burns without any residue and produces a great deal of heat, making it a clean and efficient fuel', 'It cannot be used for cooking', 'It produces more smoke than firewood', 'It is more expensive with no environmental benefit'], correctIndex: 0, explanation: 'Biogas burns without smoke, leaves no residue, and produces significant heat, making it a clean and efficient source of energy compared to conventional fuels like firewood.', difficulty: 'medium' },
  { id: 'mhw-59', type: 'mcq', question: 'The slurry left after biogas generation (spent slurry) is often used as a:', options: ['Highly toxic waste requiring special disposal', 'Good biofertiliser rich in nitrogen and phosphorus', 'Fuel source with high calorific value', 'Antibiotic precursor'], correctIndex: 1, explanation: 'The leftover slurry from a biogas plant, still rich in nutrients, is used as an excellent biofertiliser for crops.', difficulty: 'medium' },
  { id: 'mhw-60', type: 'assertion', question: 'Assertion (A): Cattle dung is a preferred raw material for biogas plants in many rural areas.\nReason (R): Cattle dung is rich in cellulolytic and methanogenic microbes originating from the rumen, which readily ferment the dung anaerobically to release methane-rich biogas.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The natural richness of cattle dung in methanogens (from the rumen) directly explains its suitability and preference as biogas plant feedstock.', difficulty: 'medium' },
  { id: 'mhw-61', type: 'count', question: 'Consider the following statements about biogas production:\n1. Methanogens are anaerobic bacteria that produce methane from cellulosic material.\n2. Methanobacterium is an example of a methanogenic bacterium.\n3. The floating cover of a biogas plant sinks down as gas accumulates.\n4. The spent slurry from a biogas plant can be used as a biofertiliser.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — the floating cover rises, not sinks, as gas accumulates.', difficulty: 'medium' },

  // ============ MICROBES AS BIOCONTROL AGENTS ============
  { id: 'mhw-62', type: 'mcq', question: 'The use of biological methods (living organisms or their products) to control pests and diseases, thereby minimising reliance on toxic chemicals, is called:', options: ['Chemical control', 'Biological control (biocontrol)', 'Genetic control only', 'Mechanical control'], correctIndex: 1, explanation: 'Biological control refers to using biological methods for controlling plant diseases and pests, avoiding the excessive use of harmful chemical pesticides and fertilisers.', difficulty: 'easy' },
  { id: 'mhw-63', type: 'mcq', question: 'The bacterium widely used as a biopesticide to control caterpillar and butterfly larvae/insect pests, and whose toxin gene has also been used in genetically modified crops, is:', options: ['Bacillus thuringiensis', 'Rhizobium leguminosarum', 'Azotobacter chroococcum', 'Trichoderma harzianum'], correctIndex: 0, explanation: 'Bacillus thuringiensis (Bt) is widely used as a biopesticide; it produces crystal proteins toxic to specific insect larvae, and its toxin gene has also been used to create Bt-transgenic crops.', difficulty: 'easy' },
  { id: 'mhw-64', type: 'mcq', question: 'The commercially available biopesticide formulation of Bacillus thuringiensis is prepared in the form of:', options: ['Dried spores mixed with water and sprayed on vulnerable plants', 'Liquid antibiotic solutions', 'Solid pellets fed directly to animals', 'Gaseous fumigants'], correctIndex: 0, explanation: 'Bt biopesticides are available as dried spores that are mixed with water and sprayed onto plants susceptible to insect attack.', difficulty: 'medium' },
  { id: 'mhw-65', type: 'mcq', question: 'When a Bt toxin protein is ingested by an insect larva, it kills the larva because the protein:', options: ['Is inactive in the insect and does not affect it at all', 'Is present in the bacterium in an inactive form but is converted into an active toxin form in the alkaline (basic) gut of the insect', 'Directly attacks the insect through skin contact only', 'Kills the plant instead of the insect'], correctIndex: 1, explanation: 'The Bt toxin protein exists in an inactive form in the bacterium; it becomes active only in the alkaline pH of the insect gut, where it damages the gut lining, ultimately killing the larva.', difficulty: 'hard' },
  { id: 'mhw-66', type: 'mcq', question: 'Trichoderma species, used as effective biocontrol agents against several plant pathogens, are examples of:', options: ['Free-living fungi commonly found in root ecosystems', 'Parasitic protozoa', 'Nitrogen-fixing bacteria', 'Methanogenic archaea'], correctIndex: 0, explanation: 'Trichoderma is a genus of free-living fungi commonly found in the root ecosystem, effective as a biocontrol agent against several plant pathogens.', difficulty: 'medium' },
  { id: 'mhw-67', type: 'mcq', question: 'Baculoviruses, used in species-specific and narrow-spectrum biological control of insect pests, are pathogens that mainly attack:', options: ['Insects and other arthropods', 'Only bacteria', 'Only plants directly', 'Only humans'], correctIndex: 0, explanation: 'Baculoviruses are pathogens that attack insects and other arthropods; most baculoviruses used as biocontrol agents belong to the genus Nucleopolyhedrovirus.', difficulty: 'medium' },
  { id: 'mhw-68', type: 'mcq', question: 'The genus of baculovirus most commonly used as a biological control agent, known for its narrow spectrum insecticidal application, is:', options: ['Nucleopolyhedrovirus', 'Bacteriophage', 'Retrovirus', 'Adenovirus'], correctIndex: 0, explanation: 'Nucleopolyhedrovirus (NPV) is the genus of baculovirus most used in the biological control of insect pests, considered excellent species-specific, narrow-spectrum insecticidal agents.', difficulty: 'medium' },
  { id: 'mhw-69', type: 'mcq', question: 'A major advantage of baculoviruses as biocontrol agents, distinguishing them from broad-spectrum chemical pesticides, is that they:', options: ['Have almost no negative effect on plants, mammals, birds, fish or non-target insects', 'Are highly toxic to all forms of life', 'Persist permanently in the environment, causing pollution', 'Kill all insects, including beneficial ones, indiscriminately'], correctIndex: 0, explanation: 'Baculoviruses have a narrow host range and are considered ideal biocontrol agents in Integrated Pest Management (IPM) programmes due to minimal impact on non-target organisms.', difficulty: 'medium' },
  { id: 'mhw-70', type: 'assertion', question: 'Assertion (A): Bacillus thuringiensis-based biopesticides are considered environmentally safer than synthetic chemical pesticides.\nReason (R): The Bt toxin is highly specific, becoming active only within the alkaline gut of susceptible insect larvae, and does not generally harm non-target organisms.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The specificity and activation mechanism of the Bt toxin correctly explains why Bt-based biopesticides are considered safer for the environment than broad-spectrum chemicals.', difficulty: 'medium' },
  { id: 'mhw-71', type: 'assertion', question: 'Assertion (A): Baculoviruses are considered ideal biological control agents in Integrated Pest Management programmes.\nReason (R): Baculoviruses possess a narrow, species-specific host range and generally do not harm plants, mammals, birds, fish or beneficial non-target insects.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The narrow host specificity of baculoviruses, sparing non-target organisms, correctly explains their suitability for use in Integrated Pest Management.', difficulty: 'medium' },
  { id: 'mhw-72', type: 'count', question: 'Consider the following statements about biocontrol agents:\n1. Bacillus thuringiensis is used as a biopesticide against insect larvae.\n2. Trichoderma species are used to control certain plant pathogens.\n3. Baculoviruses used for biocontrol are broad-spectrum agents that affect a wide range of organisms.\n4. The Bt toxin protein becomes active in the acidic gut of susceptible insects.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Statements 1 and 2 are correct. Statement 3 is wrong (baculoviruses are narrow-spectrum, not broad-spectrum), and statement 4 is wrong (Bt toxin becomes active in the alkaline, not acidic, gut).', difficulty: 'hard' },
  { id: 'mhw-73', type: 'count', question: 'Consider the following statements about biological control:\n1. Biological control reduces dependence on toxic chemical pesticides and fertilisers.\n2. Ladybird beetles and dragonflies are examples of microbial biocontrol agents.\n3. Bt toxin genes have been used in developing genetically modified crops.\n4. Biocontrol agents are generally more species-specific compared to broad-spectrum chemical pesticides.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is wrong — ladybird beetles and dragonflies are biocontrol organisms, but they are not microbes.', difficulty: 'medium' },
  { id: 'mhw-74', type: 'statement', question: 'Statement I: Excessive and indiscriminate use of chemical pesticides can be harmful to the environment and non-target organisms.\nStatement II: Biological control methods using microbes such as Bacillus thuringiensis and baculoviruses provide effective, more environmentally sound alternatives.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 0, explanation: 'Both statements correctly reflect the rationale behind promoting microbial biocontrol agents as safer alternatives to indiscriminate chemical pesticide use.', difficulty: 'easy' },
  { id: 'mhw-75', type: 'matching', question: 'Match Column I (biocontrol agent) with Column II (target/role):\nColumn I: A. Bacillus thuringiensis  B. Trichoderma  C. Nucleopolyhedrovirus (baculovirus)  D. Ladybird beetle\nColumn II: i. Non-microbial predator of aphids  ii. Controls certain plant pathogens  iii. Narrow-spectrum insecticidal virus  iv. Produces toxin against insect larvae', options: ['A-iv, B-ii, C-iii, D-i', 'A-i, B-ii, C-iii, D-iv', 'A-iv, B-iii, C-ii, D-i', 'A-ii, B-iv, C-i, D-iii'], correctIndex: 0, explanation: 'Bt — insect larvae toxin; Trichoderma — plant pathogen control; Nucleopolyhedrovirus — narrow-spectrum insecticidal virus; Ladybird beetle — non-microbial aphid predator.', difficulty: 'medium' },

  // ============ MICROBES AS BIOFERTILISERS ============
  { id: 'mhw-76', type: 'mcq', question: 'Organisms that enrich the nutrient quality of soil, mainly by fixing atmospheric nitrogen, and are used as an alternative to chemical fertilisers, are called:', options: ['Biopesticides', 'Biofertilisers', 'Bioremediation agents', 'Antibiotics'], correctIndex: 1, explanation: 'Biofertilisers are organisms that enrich the nutrient quality of soil, mainly through the natural process of nitrogen fixation.', difficulty: 'easy' },
  { id: 'mhw-77', type: 'mcq', question: 'The symbiotic bacterium present in the root nodules of leguminous plants, capable of fixing atmospheric nitrogen, belongs to the genus:', options: ['Azotobacter', 'Rhizobium', 'Nostoc', 'Trichoderma'], correctIndex: 1, explanation: 'Rhizobium is a symbiotic bacterium found in the root nodules of leguminous plants and is capable of fixing atmospheric nitrogen.', difficulty: 'easy' },
  { id: 'mhw-78', type: 'mcq', question: 'Free-living (non-symbiotic) bacteria that fix atmospheric nitrogen and improve nutrient availability of soil, without needing a plant host, include organisms such as:', options: ['Rhizobium', 'Azospirillum and Azotobacter', 'Lactobacillus', 'Aspergillus niger'], correctIndex: 1, explanation: 'Azospirillum and Azotobacter are free-living nitrogen-fixing bacteria that enhance soil fertility without requiring symbiosis with plant roots.', difficulty: 'medium' },
  { id: 'mhw-79', type: 'mcq', question: 'Cyanobacteria, an important group of biofertilisers found in aquatic and terrestrial environments, are also called:', options: ['Blue-green algae', 'Green algae', 'Brown algae', 'Red algae'], correctIndex: 0, explanation: 'Cyanobacteria are photosynthetic, nitrogen-fixing organisms often called blue-green algae, including examples such as Nostoc, Anabaena and Oscillatoria.', difficulty: 'easy' },
  { id: 'mhw-80', type: 'mcq', question: 'Which of the following is NOT an example of a nitrogen-fixing cyanobacterium (blue-green algae)?', options: ['Nostoc', 'Anabaena', 'Oscillatoria', 'Rhizobium'], correctIndex: 3, explanation: 'Rhizobium is a bacterium, not a cyanobacterium. Nostoc, Anabaena and Oscillatoria are all examples of nitrogen-fixing cyanobacteria.', difficulty: 'easy' },
  { id: 'mhw-81', type: 'mcq', question: 'Cyanobacteria play a significant role in adding organic matter and nitrogen compounds particularly in:', options: ['Rocky mountain soils', 'Paddy fields, enhancing soil fertility for rice cultivation', 'Sandy desert soils', 'Frozen tundra regions'], correctIndex: 1, explanation: 'Cyanobacteria add organic matter and increase soil fertility, and are especially important in paddy fields, where they significantly contribute nitrogen.', difficulty: 'medium' },
  { id: 'mhw-82', type: 'mcq', question: 'The symbiotic association between a fungus and the roots of higher plants, which helps in enhanced uptake of water and mineral nutrients (especially phosphorus), is called:', options: ['Rhizosphere association', 'Mycorrhiza', 'Lichen', 'Nodulation'], correctIndex: 1, explanation: 'Mycorrhiza is a symbiotic association between fungi and the roots of higher plants, benefiting the plant with better phosphorus absorption and improving resistance to root pathogens.', difficulty: 'medium' },
  { id: 'mhw-83', type: 'mcq', question: 'A well-known example of a fungus that forms mycorrhizal associations, used as biofertiliser, is:', options: ['Glomus', 'Aspergillus niger', 'Penicillium notatum', 'Trichoderma polysporum'], correctIndex: 0, explanation: 'Glomus is a fungus that forms mycorrhizal associations with plant roots and is used commonly as a biofertiliser.', difficulty: 'medium' },
  { id: 'mhw-84', type: 'mcq', question: 'Plants that form mycorrhizal associations with the fungus Glomus generally show improved resistance to which type of stress?', options: ['Root-borne pathogens and drought/salt-related stress', 'Only cold stress', 'Only insect pest attack', 'Only excessive sunlight'], correctIndex: 0, explanation: 'Plants with mycorrhizal associations generally show increased resistance to root-borne pathogens, general (and specific) increase in plant growth and development, and resistance to drought and salt-related stresses.', difficulty: 'medium' },
  { id: 'mhw-85', type: 'assertion', question: 'Assertion (A): Rhizobium fixes atmospheric nitrogen only when growing within the root nodules of a leguminous plant, and not when free-living in the soil.\nReason (R): Rhizobium is a symbiotic bacterium, and the specialised conditions (such as low oxygen environment) required for its nitrogenase enzyme to function effectively are provided within the root nodule.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The specialised low-oxygen environment of the root nodule, essential for nitrogenase activity, correctly explains why Rhizobium fixes nitrogen effectively mainly in symbiosis.', difficulty: 'hard' },
  { id: 'mhw-86', type: 'assertion', question: 'Assertion (A): Cyanobacteria are considered important biofertilisers, especially in paddy fields.\nReason (R): Cyanobacteria are photosynthetic and can fix atmospheric nitrogen, thereby enriching the soil with both organic matter and nitrogen compounds.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Since cyanobacteria are both photosynthetic and nitrogen-fixing, they enrich the soil in exactly the way described in R, correctly explaining their importance as biofertilisers.', difficulty: 'medium' },
  { id: 'mhw-87', type: 'assertion', question: 'Assertion (A): Mycorrhizal associations improve a plant\'s ability to absorb phosphorus from the soil.\nReason (R): The fungal hyphae in a mycorrhizal association greatly increase the effective surface area for absorption, allowing access to soil phosphorus beyond the reach of the plant\'s own root hairs.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The increased absorptive surface area provided by fungal hyphae correctly explains the improved phosphorus uptake seen in mycorrhizal plants.', difficulty: 'medium' },
  { id: 'mhw-88', type: 'count', question: 'Consider the following statements about biofertilisers:\n1. Rhizobium is a symbiotic, nitrogen-fixing bacterium found in leguminous root nodules.\n2. Azospirillum and Azotobacter are examples of free-living nitrogen-fixing bacteria.\n3. Cyanobacteria (blue-green algae) can also fix atmospheric nitrogen.\n4. Mycorrhiza refers exclusively to a bacterial association with plant roots.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 3 are correct. Statement 4 is wrong — mycorrhiza refers to a fungal, not bacterial, association with plant roots.', difficulty: 'medium' },
  { id: 'mhw-89', type: 'count', question: 'Consider the following examples:\n1. Nostoc\n2. Anabaena\n3. Rhizobium\n4. Glomus\n5. Azotobacter\nHow many of the above are examples of nitrogen-fixing cyanobacteria (blue-green algae)?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Nostoc and Anabaena are cyanobacteria. Rhizobium and Azotobacter are bacteria (not cyanobacteria), and Glomus is a fungus. So only two of the five are cyanobacteria.', difficulty: 'medium' },
  { id: 'mhw-90', type: 'statement', question: 'Statement I: Biofertilisers can completely replace the need for all chemical fertilisers in modern agriculture.\nStatement II: Biofertilisers such as Rhizobium, Azotobacter and cyanobacteria enrich soil nutrient quality mainly through biological nitrogen fixation.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 3, explanation: 'Statement I is an overstatement and is incorrect — biofertilisers are used as more environmentally friendly supplements/alternatives to reduce chemical fertiliser dependence, not necessarily as a complete standalone replacement in all contexts as commonly emphasised. Statement II correctly describes their mechanism.', difficulty: 'medium' },
  { id: 'mhw-91', type: 'matching', question: 'Match Column I (biofertiliser/organism) with Column II (type/role):\nColumn I: A. Rhizobium  B. Azotobacter  C. Nostoc  D. Glomus\nColumn II: i. Free-living nitrogen-fixing bacterium  ii. Mycorrhizal fungus improving phosphorus uptake  iii. Symbiotic nitrogen-fixing bacterium in root nodules  iv. Nitrogen-fixing cyanobacterium', options: ['A-iii, B-i, C-iv, D-ii', 'A-i, B-iii, C-ii, D-iv', 'A-iii, B-iv, C-i, D-ii', 'A-ii, B-i, C-iii, D-iv'], correctIndex: 0, explanation: 'Rhizobium — symbiotic bacterium in root nodules; Azotobacter — free-living nitrogen-fixing bacterium; Nostoc — nitrogen-fixing cyanobacterium; Glomus — mycorrhizal fungus.', difficulty: 'medium' },

  // ============ MIXED / REVISION ============
  { id: 'mhw-92', type: 'mcq', question: 'Which of the following is an example of microbes being used to improve nutritional quality of food, rather than in industrial or environmental applications?', options: ['Lactic acid bacteria producing vitamin B12 during curd formation', 'Streptomyces griseus producing streptomycin', 'Trichoderma controlling plant pathogens', 'Methanogens producing biogas'], correctIndex: 0, explanation: 'The production of vitamin B12 by lactic acid bacteria during curd formation directly improves the nutritional quality of a food item, unlike the other examples, which serve industrial or environmental purposes.', difficulty: 'medium' },
  { id: 'mhw-93', type: 'mcq', question: 'Which of the following pairs is INCORRECTLY matched?', options: ['Saccharomyces cerevisiae — Ethanol production', 'Streptococcus — Streptokinase', 'Aspergillus niger — Citric acid', 'Bacillus thuringiensis — Statins'], correctIndex: 3, explanation: 'Bacillus thuringiensis is used as a biopesticide, not for statin production. Statins are produced using the yeast Monascus purpureus.', difficulty: 'medium' },
  { id: 'mhw-94', type: 'assertion', question: 'Assertion (A): Microbes play a crucial role in domains as diverse as food processing, industrial production, environmental cleanup, agriculture and medicine.\nReason (R): Different microbial species possess unique metabolic capabilities that can be harnessed for producing specific beneficial substances or carrying out targeted biochemical transformations.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The diverse metabolic capacities of different microbes correctly explain why they find application across such a wide range of human welfare domains.', difficulty: 'medium' },
  { id: 'mhw-95', type: 'count', question: 'Consider the following statements comparing biofertilisers and biopesticides:\n1. Biofertilisers primarily enhance soil nutrient status.\n2. Biopesticides primarily control pests and pathogens using biological means.\n3. Rhizobium is an example of a biopesticide.\n4. Bacillus thuringiensis is an example of a biofertiliser.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Statements 1 and 2 are correct. Statements 3 and 4 are both wrong — Rhizobium is a biofertiliser, and Bacillus thuringiensis is a biopesticide (their roles are reversed in the statements).', difficulty: 'medium' },
  { id: 'mhw-96', type: 'count', question: 'Consider the following statements:\n1. Fermented beverages like beer and wine do not involve distillation.\n2. Antibiotics can be produced by bacteria as well as fungi.\n3. All biocontrol agents used in agriculture are exclusively bacteria.\n4. Biogas plants rely on anaerobic microbial digestion of organic waste.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — biocontrol agents include bacteria (Bt), fungi (Trichoderma) and viruses (baculoviruses), not exclusively bacteria.', difficulty: 'medium' },
  { id: 'mhw-97', type: 'assertion', question: 'Assertion (A): The use of microbes in agriculture and industry is often seen as more sustainable than relying solely on synthetic chemicals.\nReason (R): Microbial processes such as nitrogen fixation and biological pest control are naturally occurring, renewable, and generally cause less long-term environmental damage compared to persistent chemical fertilisers and pesticides.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The natural, renewable and generally lower environmental impact of microbial processes correctly explains why they are regarded as more sustainable alternatives.', difficulty: 'medium' },
  { id: 'mhw-98', type: 'statement', question: 'Statement I: Microbes used in sewage treatment are the same as those used to produce antibiotics.\nStatement II: Both sewage treatment microbes and antibiotic-producing microbes are examples of how naturally occurring microorganisms are harnessed for human welfare, though they involve different species and different processes.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 3, explanation: 'Statement I is incorrect — the microbes used in sewage treatment (heterotrophic bacteria, methanogens) are generally different from antibiotic-producing microbes (e.g., Penicillium, Streptomyces). Statement II is correct.', difficulty: 'medium' },
  { id: 'mhw-99', type: 'count', question: 'Consider the following microbes:\n1. Lactobacillus\n2. Saccharomyces cerevisiae\n3. Streptomyces griseus\n4. Trichoderma polysporum\n5. Rhizobium\nHow many of the above are primarily associated with producing antibiotics or immunosuppressive drugs, rather than food fermentation or biofertilisation?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Streptomyces griseus (streptomycin) and Trichoderma polysporum (cyclosporin A) are associated with antibiotic/immunosuppressive drug production. Lactobacillus and Saccharomyces are used in food fermentation, and Rhizobium is a biofertiliser.', difficulty: 'hard' },
  { id: 'mhw-100', type: 'mcq', question: 'Which of the following best summarises the overall theme of the chapter "Microbes in Human Welfare"?', options: ['Microbes are exclusively harmful and cause disease', 'Microbes have diverse beneficial applications in food, industry, sewage treatment, energy production, agriculture and medicine', 'Microbes have no significant role in human affairs', 'Microbes are used only for producing alcohol'], correctIndex: 1, explanation: 'The chapter highlights the wide range of beneficial roles microbes play across household products, industry, environmental management, agriculture and medicine.', difficulty: 'easy' },
];
